class Solution {
public:
    int findInteger(int k, int digit1, int digit2) {
        long long best = LLONG_MAX;
        function<void(long long, int)> dfs = [&](long long value, int length) {
            if (length > 10 || value > INT_MAX) return;
            if (value > k && value % k == 0) best = min(best, value);
            if (length == 10) return;
            for (int d : {digit1, digit2}) {
                if (value == 0 && d == 0) continue;
                dfs(value * 10 + d, length + 1);
            }
        };
        dfs(0, 0);
        return best == LLONG_MAX ? -1 : (int)best;
    }
};
